mapper.select:
select 
  from wms_count c left join mst_item i on i.item_id = c.item_id
 where c.plant_cd = #{plantCd}
   and c.status = #{status}
 order by c.count_id desc
 limit #{limit}

mapper.sql:
 from wms_count c left join mst_item i on i.item_id = c.item_id
where c.plant_cd = #{plantCd}
  and c.status = #{status}

mapper.update:
update wms_count set status = 'POSTED', posted_at = now(), posted_by = #{by}, row_ver = row_ver + 1, updated_at = now(),
       updated_by = #{by}
 where count_id = #{id} and status = 'REVIEW'

mapper.insert:
with recursive scope as (
    select node_id, 1 as lv from mst_equip_hier where node_id = #{scopeId}
    union all
    select c.node_id, s.lv + 1 from scope s join mst_equip_hier c on c.parent_id = s.node_id where s.lv < 20
)
insert into wms_count_line (comp_cd, count_id, node_id, item_id, lot_id, stock_status, created_by, updated_by)
select hb_current_comp(), #{countId}, s.node_id, s.item_id, s.lot_id, s.stock_status, #{by}, #{by}
  from inv_stock s
 where s.plant_cd = #{plantCd} and s.qty <> 0
   and s.node_id in (select node_id from scope)
   and s.item_id = #{itemId}
 order by s.node_id, s.item_id, s.lot_id, s.stock_status

mapper.select:
select  from wms_count_line l join mst_item i on i.item_id = l.item_id
 where l.count_id = #{countId}
 order by path, i.item_cd, lot_no nulls first, l.stock_status, l.recount_no

mapper.update:
update wms_count_line set book_qty = #{bookQty}, counted_qty = #{countedQty}, counted_at = #{countedAt},
       counted_by = #{by}, counted_worker_id = #{workerId}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where line_id = #{lineId}

mapper.select:
select  from sys_period_close
 where plant_cd = #{plantCd} and module_cd = 'INV' and period between #{fromPeriod} and #{toPeriod}
 order by period

mapper.update:
update sys_period_close set status = 'CLOSED', closed_at = now(), closed_by = #{by}, row_ver = row_ver + 1, updated_at = now(),
       updated_by = #{by}
 where close_id = #{id} and row_ver = #{rowVer} and status = 'REOPENED'

update sys_period_close set status = 'REOPENED', reopened_at = now(), reopened_by = #{by}, reason = #{reason},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where close_id = #{id} and row_ver = #{rowVer} and status = 'CLOSED'
